input.command:
cd /home/claude && cat > roadmap.html << 'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>The Luxora Growth Engine™ - 90-Day Roadmap</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            padding: 40px 20px;
        }

        .container {
            max-width: 1400px;
            margin: 0 auto;
            background: white;
            border-radius: 20px;
            box-shadow: 0 20px 60px rgba(0,0,0,0.3);
            overflow: hidden;
        }

        .header {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 40px;
            text-align: center;
        }

        .header h1 {
            font-size: 2.5em;
            margin-bottom: 10px;
            font-weight: 700;
        }

        .header p {
            font-size: 1.2em;
            opacity: 0.95;
        }

        .content {
            display: grid;
            grid-template-columns: 300px 1fr;
            gap: 0;
        }

        .timeline {
            background: #f8f9fa;
            padding: 40px 20px;
            border-right: 3px solid #e9ecef;
            position: relative;
        }

        .timeline::before {
            content: '';
            position: absolute;
            left: 50%;
            top: 40px;
            bottom: 40px;
            width: 4px;
            background: linear-gradient(180deg, #667eea 0%, #764ba2 100%);
            transform: translateX(-50%);
        }

        .phase {
            position: relative;
            margin-bottom: 60px;
            text-align: center;
        }

        .phase:last-child {
            margin-bottom: 0;
        }

        .phase-circle {
            width: 60px;
            height: 60px;
            background: white;
            border: 4px solid #667eea;
            border-radius: 50%;
            margin: 0 auto 15px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            font-size: 1.1em;
            color: #667eea;
            position: relative;
            z-index: 1;
        }

        .phase-label {
            font-weight: 600;
            color: #495057;
            font-size: 0.95em;
        }

        .details {
            padding: 40px 50px;
        }

        .phase-section {
            margin-bottom: 50px;
        }

        .phase-section h2 {
            color: #667eea;
            font-size: 1.8em;
            margin-bottom: 20px;
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .phase-badge {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 5px 15px;
            border-radius: 20px;
            font-size: 0.6em;
            font-weight: 600;
        }

        .step-card {
            background: #f8f9fa;
            border-left: 4px solid #667eea;
            padding: 20px 25px;
            margin-bottom: 20px;
            border-radius: 8px;
            transition: all 0.3s ease;
        }

        .step-card:hover {
            transform: translateX(5px);
            box-shadow: 0 5px 15px rgba(102, 126, 234, 0.2);
        }

        .step-title {
            font-weight: 700;
            color: #212529;
            font-size: 1.1em;
            margin-bottom: 10px;
        }

        .step-description {
            color: #6c757d;
            line-height: 1.6;
            margin-bottom: 10px;
        }

        .deliverable-tag {
            display: inline-block;
            background: #e7f3ff;
            color: #0066cc;
            padding: 4px 12px;
            border-radius: 15px;
            font-size: 0.85em;
            font-weight: 600;
            margin-top: 5px;
        }

        .timeline-divider {
            border: 0;
            height: 2px;
            background: linear-gradient(90deg, transparent, #dee2e6, transparent);
            margin: 40px 0;
        }

        .guarantee-box {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 30px;
            border-radius: 15px;
            margin-top: 40px;
            text-align: center;
        }

        .guarantee-box h3 {
            font-size: 1.5em;
            margin-bottom: 15px;
        }

        .guarantee-box p {
            font-size: 1.1em;
            line-height: 1.6;
            opacity: 0.95;
        }

        @media print {
            body {
                background: white;
                padding: 0;
            }
            .container {
                box-shadow: none;
            }
            .step-card {
                page-break-inside: avoid;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>The Luxora Growth Engine™</h1>
            <p>Your 90-Day Transformation Roadmap</p>
        </div>

        <div class="content">
            <div class="timeline">
                <div class="phase">
                    <div class="phase-circle">START</div>
                    <div class="phase-label">Days 1-7</div>
                </div>
                <div class="phase">
                    <div class="phase-circle">30</div>
                    <div class="phase-label">Month 1</div>
                </div>
                <div class="phase">
                    <div class="phase-circle">60</div>
                    <div class="phase-label">Month 2</div>
                </div>
                <div class="phase">
                    <div class="phase-circle">90</div>
                    <div class="phase-label">Complete</div>
                </div>
            </div>

            <div class="details">
                <!-- PHASE 1: ENROLLMENT -->
                <div class="phase-section">
                    <h2>
                        <span class="phase-badge">IMMEDIATE ACTION</span>
                        Welcome & Onboarding
                    </h2>

                    <div class="step-card">
                        <div class="step-title">📋 Receive Your 90-Day Roadmap</div>
                        <div class="step-description">
                            You'll receive this comprehensive roadmap immediately upon enrollment to guide you through every step of your transformation journey.
                        </div>
                        <span class="deliverable-tag">📄 PDF Included</span>
                    </div>

                    <div class="step-card">
                        <div class="step-title">📞 STEP 1: Book Your Strategy Kickoff Call</div>
                        <div class="step-description">
                            This is our first working session together. We'll review your business goals, walk through the 90-day roadmap, begin your Market Blueprint analysis, and answer questions. <strong>This is a working session, not a welcome call. Come prepared to go deep.</strong>
                        </div>
                    </div>

                    <div class="step-card">
                        <div class="step-title">📝 STEP 2: Complete Your Onboarding</div>
                        <div class="step-description">
                            Fill out your onboarding survey and checklist within 5-7 days. This includes business information, goals, creative asset upload instructions, access credentials for your CRM and ad accounts, and team information for sales training coordination.
                        </div>
                    </div>

                    <div class="step-card">
                        <div class="step-title">📸 STEP 3: Gather Your Creative Assets</div>
                        <div class="step-description">
                            Collect 3-5 pieces of content for your ad campaigns: before/after photos, video testimonials, behind-the-scenes photos, or promotional videos. Don't have these yet? No problem—we'll provide you with a Creative Asset Guide.
                        </div>
                    </div>

                    <div class="step-card">
                        <div class="step-title">💻 STEP 4: Schedule Your Ad & Tech Call</div>
                        <div class="step-description">
                            Book this call at least 48 hours after completing your onboarding checklist. Our tech team will review your Ads, AI Integration, and CRM setup. Bring any tech questions you have.
                        </div>
                    </div>
                </div>

                <hr class="timeline-divider">

                <!-- PHASE 2: FOUNDATION -->
                <div class="phase-section">
                    <h2>
                        <span class="phase-badge">DAYS 8-30</span>
                        Foundation & Systems Build
                    </h2>

                    <div class="step-card">
                        <div class="step-title">💰 Complete Lifetime Value Sales Playbook</div>
                        <div class="step-description">
                            Master the art of maximizing client lifetime value with our comprehensive sales framework. You'll receive the playbook, comprehension quiz, and answer key to ensure full team understanding and implementation.
                        </div>
                        <span class="deliverable-tag">📄 Playbook PDF</span>
                        <span class="deliverable-tag">✅ Quiz PDF</span>
                        <span class="deliverable-tag">🔑 Answer Key PDF</span>
                    </div>

                    <div class="step-card">
                        <div class="step-title">🎫 Ultimate MedSpa Membership Playbook</div>
                        <div class="step-description">
                            Build a recurring revenue engine with a strategic membership program. Learn how to structure, price, and sell memberships that keep clients coming back month after month.
                        </div>
                        <span class="deliverable-tag">📄 Playbook PDF</span>
                        <span class="deliverable-tag">✅ Quiz PDF</span>
                        <span class="deliverable-tag">🔑 Answer Key PDF</span>
                    </div>

                    <div class="step-card">
                        <div class="step-title">⭐ Reputation Engine Playbook</div>
                        <div class="step-description">
                            Generate 10+ five-star reviews per week with our proven system. Maintain a 4.8+ star rating while building unshakeable social proof that converts prospects into clients.
                        </div>
                        <span class="deliverable-tag">📄 Playbook PDF</span>
                        <span class="deliverable-tag">✅ Quiz PDF</span>
                        <span class="deliverable-tag">🔑 Answer Key PDF</span>
                    </div>

                    <div class="step-card">
                        <div class="step-title">🤝 Partnership & Collaboration Framework Playbook</div>
                        <div class="step-description">
                            Unlock new revenue streams through strategic partnerships. Learn how to identify, approach, and create win-win collaborations with complementary businesses.
                        </div>
                        <span class="deliverable-tag">📄 Playbook PDF</span>
                        <span class="deliverable-tag">✅ Quiz PDF</span>
                        <span class="deliverable-tag">🔑 Answer Key PDF</span>
                    </div>
                </div>

                <hr class="timeline-divider">

                <!-- PHASE 3: OPTIMIZATION -->
                <div class="phase-section">
                    <h2>
                        <span class="phase-badge">DAYS 31-60</span>
                        Revenue Optimization & Scaling
                    </h2>

                    <div class="step-card">
                        <div class="step-title">📦 Package & Upsell Architecture Framework Playbook</div>
                        <div class="step-description">
                            Design irresistible service packages and upsell strategies that increase average transaction value. Learn the psychology and structure behind high-converting offers.
                        </div>
                        <span class="deliverable-tag">📄 Playbook PDF</span>
                        <span class="deliverable-tag">✅ Quiz PDF</span>
                        <span class="deliverable-tag">🔑 Answer Key PDF</span>
                    </div>

                    <div class="step-card">
                        <div class="step-title">🔆 Laser ROI Playbook</div>
                        <div class="step-description">
                            Maximize profitability on your laser services with data-driven pricing, promotion, and positioning strategies. Turn your equipment investment into a revenue powerhouse.
                        </div>
                        <span class="deliverable-tag">📄 Playbook PDF</span>
                        <span class="deliverable-tag">✅ Quiz PDF</span>
                        <span class="deliverable-tag">🔑 Answer Key PDF</span>
                    </div>

                    <div class="step-card">
                        <div class="step-title">📊 Ongoing Performance Reviews</div>
                        <div class="step-description">
                            Regular check-ins to review metrics, refine strategies, and ensure you're on track to hit 2× ROI in lifetime client value. We'll make adjustments as needed to keep you moving forward.
                        </div>
                    </div>
                </div>

                <hr class="timeline-divider">

                <!-- PHASE 4: COMPLETION -->
                <div class="phase-section">
                    <h2>
                        <span class="phase-badge">DAYS 61-90</span>
                        Celebration & Sustainability
                    </h2>

                    <div class="step-card">
                        <div class="step-title">🎉 90-Day Celebration Event Playbook</div>
                        <div class="step-description">
                            <strong>Sent 5 weeks before completion:</strong> Plan and execute a celebration event that reinforces client relationships, generates buzz, and drives revenue. Turn your transformation into a marketing event.
                        </div>
                        <span class="deliverable-tag">📄 Playbook PDF</span>
                        <span class="deliverable-tag">✅ Quiz PDF</span>
                        <span class="deliverable-tag">🔑 Answer Key PDF</span>
                    </div>

                    <div class="step-card">
                        <div class="step-title">🎯 Final Results Review</div>
                        <div class="step-description">
                            Comprehensive review of your 90-day transformation. We'll analyze your growth metrics, celebrate wins, and create a sustainability plan to maintain momentum long after the program ends.
                        </div>
                    </div>
                </div>

                <div class="guarantee-box">
                    <h3>Our 2× ROI Guarantee</h3>
                    <p>
                        If you show up, implement what we teach, and operate the system we build, you're going to see results. <strong>If you don't hit 2× ROI in lifetime client value, we'll keep working for free until you do.</strong> That's our commitment to you.
                    </p>
                </div>
            </div>
        </div>
    </div>
</body>
</html>
EOF

